using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Diagnostics;using System.Windows.Forms;using System.Web.Script.Serialization;using Microsoft.Web.WebView2.WinForms;
// Generated files and isolated profile only. Default render capture, no OS audio setters.
class AnPingSoundProbe {
 static string root=Directory.GetCurrentDirectory(),dir=Environment.GetEnvironmentVariable("CANIDELETE_CHECK_DIR"),fx;static JavaScriptSerializer js=new JavaScriptSerializer();static Stopwatch clock=Stopwatch.StartNew();
 static void Pump(int ms){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){if(clock.Elapsed.TotalSeconds>70)throw new Exception("70s limit");Application.DoEvents();Thread.Sleep(3);}}
 static string Eval(WebView2 w,string code){var t=w.CoreWebView2.ExecuteScriptAsync(code);while(!t.IsCompleted)Pump(3);return t.GetAwaiter().GetResult();}
 static void Wait(WebView2 w,string code){var until=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<until){if(Eval(w,code)=="true")return;Pump(10);}throw new Exception("wait "+code+" | "+Eval(w,"({soundOn,result:audio.lastResult,state:audio.context&&audio.context.state,end:window.__end})"));}
 static void Check(WebView2 w,string name,string code){if(Eval(w,code)!="true")throw new Exception(name);Console.WriteLine("PASS "+name);}
 static WebView2 Open(AnPingForm f){f.Show();var w=f.Controls.OfType<WebView2>().Single();while(w.CoreWebView2==null)Pump(10);Pump(500);Wait(w,"typeof S==='object'");Eval(w,"window.__cues=[];window.__end=null;audio.options.onScheduled=e=>window.__cues.push({...e,wall:performance.now()});window.chrome.webview.addEventListener('message',e=>{if(e.data.action==='scanComplete')window.__end=e.data;});");return w;}
 static void Click(WebView2 w,string selector){string pos=Eval(w,"(()=>{let r=document.querySelector("+js.Serialize(selector)+").getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};})()");var p=js.Deserialize<System.Collections.Generic.Dictionary<string,object>>(pos);foreach(string type in new[]{"mousePressed","mouseReleased"}){var t=w.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",js.Serialize(new{type,x=p["x"],y=p["y"],button="left",clickCount=1}));while(!t.IsCompleted)Pump(3);t.GetAwaiter().GetResult();}}
 static void Start(WebView2 w){Eval(w,"window.__end=null;window.chrome.webview.postMessage(JSON.stringify({action:'startScan',targets:["+js.Serialize(fx)+"]}));");}
 static void Capture(WebView2 w,string name,Action start){using(var cap=new WasapiLoopbackCapture()){cap.Start();Pump(400);start();Wait(w,"window.__end!==null");Pump(1100);var report=cap.Finish(Path.Combine(dir,name+".wav"));File.WriteAllText(Path.Combine(dir,name+"-capture.json"),js.Serialize(report));File.WriteAllText(Path.Combine(dir,name+"-events.json"),Eval(w,"({events:__cues,result:audio.lastResult,report:__end,notified:S.completionNotified})"));Console.WriteLine(name+" "+js.Serialize(report));Check(w,name+" natural end exactly once","__end.completed&&__cues.filter(x=>x.kind==='complete'&&x.session===currentScanSession).length===1");}}
 [STAThread]static int Main(){try{if(string.IsNullOrWhiteSpace(dir))throw new InvalidOperationException("CANIDELETE_CHECK_DIR must be set.");dir=Path.GetFullPath(dir);Directory.CreateDirectory(dir);Environment.SetEnvironmentVariable("WEBVIEW2_USER_DATA_FOLDER",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data","WebView2Data"));AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name,p=n=="can-i-delete"?Path.Combine(root,"can-i-delete.exe"):Path.Combine(root,"lib",n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};return Run();}catch(Exception e){Console.WriteLine(e);return 1;}}
 static int Run(){Application.EnableVisualStyles();fx=Path.Combine(dir,"fixture");Directory.CreateDirectory(fx);for(int i=0;i<12;i++)File.WriteAllText(Path.Combine(fx,"generated-"+i+".txt"),"test only");
 string phase=Environment.GetEnvironmentVariable("SOUND_TEST_PHASE");
 if(phase=="save-on"){using(var f=new AnPingForm()){var w=Open(f);Click(w,"#soundBtn");Check(w,"saved on before process exit","soundOn&&localStorage.getItem('anping.sound.enabled')==='true'");Pump(500);f.Close();}return 0;}
 if(phase=="verify-on"){using(var f=new AnPingForm()){var w=Open(f);Check(w,"enabled survives separate process restart","soundOn&&audio.enabled");Click(w,"#pick");Wait(w,"audio.context&&audio.context.state==='running'");Eval(w,"closeSheet()");Pump(700);Capture(w,"05-restarted-real-end",()=>Start(w));f.Close();}return 0;}
 using(var f=new AnPingForm()){var w=Open(f);Check(w,"fresh profile muted","!soundOn&&!audio.enabled");Click(w,"#soundBtn");Wait(w,"audio.context&&audio.context.state==='running'");Pump(1000);Check(w,"user enabled saved","localStorage.getItem('anping.sound.enabled')==='true'");Capture(w,"01-enabled-real-end",()=>Start(w));f.Close();}
 Pump(200);
 using(var f=new AnPingForm()){var w=Open(f);Check(w,"reopened enabled without toggling again","soundOn&&audio.enabled&&audio.context===null");Click(w,"#pick");Wait(w,"audio.context&&audio.context.state==='running'");Eval(w,"closeSheet()");Pump(700);
 Capture(w,"02-reopened-real-end",()=>Start(w));
 Eval(w,"window.__cues=[];audio.options.onScheduled=e=>{__cues.push({...e,wall:performance.now()});if(e.kind==='complete')window.dispatchEvent(new Event('blur'));};");Capture(w,"03-blur-at-real-end",()=>Start(w));
 f.WindowState=FormWindowState.Minimized;Pump(300);Console.WriteLine("BACKGROUND "+Eval(w,"({visibility:document.visibilityState,focus:document.hasFocus()})"));Eval(w,"window.__cues=[];");Capture(w,"04-minimized-real-end",()=>Start(w));f.WindowState=FormWindowState.Normal;f.Activate();Pump(300);
 Eval(w,"if(legend.classList.contains('show'))$('legendOk').click();");Click(w,"#soundBtn");Check(w,"mute saved and active audio stopped","!soundOn&&audio.nodes.size===0&&localStorage.getItem('anping.sound.enabled')==='false'");Eval(w,"window.__cues=[]");Start(w);Wait(w,"window.__end!==null");Check(w,"muted natural end does not play","__end.completed&&__cues.length===0");f.Close();}
 using(var f=new AnPingForm()){var w=Open(f);Check(w,"reopened remains muted","!soundOn&&!audio.enabled");f.Close();}
 Console.WriteLine("PASS real scans, persisted switch, blur and background; waveform validation still required");return 0;}
}
